-- =====================================================================================
-- Academic Scheduling - V1 schema (Flyway)
-- Source: Phase 2 report, TR2.1-TR2.11, class descriptions, User's Guide section 5.
-- Portable SQL: runs unchanged on PostgreSQL and on H2 in PostgreSQL mode
--   (jdbc:h2:mem:sched;MODE=PostgreSQL;DATABASE_TO_LOWER=TRUE;DEFAULT_NULL_ORDERING=HIGH).
-- Conventions
--   * Ids are VARCHAR(36) generated by the application (UUID text); readable ids such as 'R-LABB'
--     are fine for fixtures. Core Platform user ids are VARCHAR(100) and are never generated here.
--   * Enums are stored as text and guarded by CHECK constraints; the values mirror
--     team3.scheduling.domain. Map them with @Enumerated(EnumType.STRING).
--   * Day of week is stored as the java.time.DayOfWeek name (MONDAY ... SUNDAY).
--   * Rooms, equipment, bookings and subjects are never deleted once referenced (ON DELETE RESTRICT):
--     FR2.5 changes a status instead, so booking history survives.
-- =====================================================================================

-- ---------- People (profiles only: identity, passwords and roles stay in the Core Platform) ----------

CREATE TABLE app_user (
    id            VARCHAR(100) PRIMARY KEY,           -- JWT subject from the Core Platform
    display_name  VARCHAR(150) NOT NULL,
    email         VARCHAR(200),
    department    VARCHAR(100)                        -- instructor's home department
    -- Deliberately NO role column: role is resolved from the token on every request (NFR1.4).
    -- Students are not stored at all: enrollment is owned by the SIS (TR1.3, TR4.4).
);

-- Scheduler.authorizedDepartments (TR3.4). Empty set = may not change anything.
CREATE TABLE scheduler_department (
    scheduler_id  VARCHAR(100) NOT NULL REFERENCES app_user (id) ON DELETE CASCADE,
    department    VARCHAR(100) NOT NULL,
    PRIMARY KEY (scheduler_id, department)
);

-- ---------- Terms (TR2.1) ----------

CREATE TABLE term (
    id            VARCHAR(36)  PRIMARY KEY,
    name          VARCHAR(100) NOT NULL UNIQUE,
    start_date    DATE         NOT NULL,
    end_date      DATE         NOT NULL,
    status        VARCHAR(20)  NOT NULL DEFAULT 'DRAFT',
    published_at  TIMESTAMP,
    CONSTRAINT ck_term_status CHECK (status IN ('DRAFT', 'PUBLISHED')),
    CONSTRAINT ck_term_dates  CHECK (end_date >= start_date),
    CONSTRAINT ck_term_published CHECK ((status = 'PUBLISHED') = (published_at IS NOT NULL))
);

-- ---------- Catalogs: Subject (TR2.2), Room (TR2.4), Equipment (TR2.5) ----------

CREATE TABLE subject (
    id                 VARCHAR(36)  PRIMARY KEY,
    course_code        VARCHAR(30)  NOT NULL UNIQUE,   -- duplicate code => import row "Needs review" (UC-12 6a)
    title              VARCHAR(200) NOT NULL,
    credit_hours       INTEGER      NOT NULL,
    default_room_type  VARCHAR(20)  NOT NULL,
    department         VARCHAR(100),                   -- nullable: the User's Guide lets a subject start without one
    CONSTRAINT ck_subject_credits CHECK (credit_hours > 0),
    CONSTRAINT ck_subject_room_type CHECK (default_room_type IN ('LECTURE_HALL', 'LAB', 'SEMINAR_ROOM'))
);

CREATE TABLE subject_equipment (                      -- Subject.typicalEquipment
    subject_id  VARCHAR(36) NOT NULL REFERENCES subject (id) ON DELETE CASCADE,
    item_type   VARCHAR(100) NOT NULL,
    PRIMARY KEY (subject_id, item_type)
);

CREATE TABLE room (
    id        VARCHAR(36)  PRIMARY KEY,
    name      VARCHAR(100) NOT NULL UNIQUE,            -- "Founders 110"; the import's room_name column looks rooms up by this
    building  VARCHAR(100) NOT NULL,
    capacity  INTEGER      NOT NULL,
    room_type VARCHAR(20)  NOT NULL,
    status    VARCHAR(20)  NOT NULL DEFAULT 'AVAILABLE',
    CONSTRAINT ck_room_capacity CHECK (capacity > 0),  -- TC-FR3.2: capacity -5 is rejected
    CONSTRAINT ck_room_type CHECK (room_type IN ('LECTURE_HALL', 'LAB', 'SEMINAR_ROOM')),
    CONSTRAINT ck_room_status CHECK (status IN ('AVAILABLE', 'MAINTENANCE', 'CHECKED_OUT'))
);

CREATE TABLE room_fixed_equipment (                   -- Room.fixedEquipment (separate from the portable catalog, FR2.2)
    room_id    VARCHAR(36)  NOT NULL REFERENCES room (id) ON DELETE CASCADE,
    item_type  VARCHAR(100) NOT NULL,
    PRIMARY KEY (room_id, item_type)
);

CREATE TABLE equipment (
    id             VARCHAR(36)  PRIMARY KEY,
    name           VARCHAR(100) NOT NULL UNIQUE,       -- import column item_name
    item_type      VARCHAR(100) NOT NULL,              -- import column type ("Projector")
    unit_count     INTEGER      NOT NULL,
    home_location  VARCHAR(200),
    status         VARCHAR(20)  NOT NULL DEFAULT 'AVAILABLE',
    CONSTRAINT ck_equipment_units CHECK (unit_count > 0),
    CONSTRAINT ck_equipment_status CHECK (status IN ('AVAILABLE', 'MAINTENANCE', 'CHECKED_OUT'))
);

-- ---------- Sections and their meetings (TR2.3) ----------

CREATE TABLE section (
    id              VARCHAR(36) PRIMARY KEY,
    term_id         VARCHAR(36) NOT NULL REFERENCES term (id)    ON DELETE CASCADE,   -- deleting a timetable removes its sections (FR1.1)
    subject_id      VARCHAR(36) NOT NULL REFERENCES subject (id) ON DELETE RESTRICT,
    section_number  VARCHAR(10) NOT NULL DEFAULT '01',
    room_id         VARCHAR(36)          REFERENCES room (id)    ON DELETE RESTRICT,  -- NULL = not placed yet; the service requires a room to place
    -- No enrolled_count column: enrollment is read from the SIS when a check needs it (TR1.3, TR4.4).
    CONSTRAINT uq_section UNIQUE (term_id, subject_id, section_number)
);

-- One section has one or more meetings: "MWF" becomes 3 WEEKLY rows, an exam is an EXAM row with a date.
CREATE TABLE section_meeting (
    id            VARCHAR(36) PRIMARY KEY,
    section_id    VARCHAR(36) NOT NULL REFERENCES section (id) ON DELETE CASCADE,
    pattern       VARCHAR(10) NOT NULL,
    day_of_week   VARCHAR(10),                          -- WEEKLY only; for dated meetings derive it from meeting_date
    meeting_date  DATE,                                 -- ONE_TIME / EXAM only
    start_time    TIME        NOT NULL,
    end_time      TIME        NOT NULL,
    CONSTRAINT ck_meeting_pattern CHECK (pattern IN ('WEEKLY', 'ONE_TIME', 'EXAM')),
    CONSTRAINT ck_meeting_day CHECK (day_of_week IS NULL OR day_of_week IN
        ('MONDAY', 'TUESDAY', 'WEDNESDAY', 'THURSDAY', 'FRIDAY', 'SATURDAY', 'SUNDAY')),
    CONSTRAINT ck_meeting_window CHECK (start_time < end_time),                         -- UC-02 5a
    CONSTRAINT ck_meeting_shape CHECK (
        (pattern = 'WEEKLY' AND day_of_week IS NOT NULL AND meeting_date IS NULL) OR
        (pattern <> 'WEEKLY' AND meeting_date IS NOT NULL AND day_of_week IS NULL))
);

CREATE TABLE section_instructor (                     -- one or more instructors per section (FR1.6)
    section_id     VARCHAR(36)  NOT NULL REFERENCES section (id)  ON DELETE CASCADE,
    instructor_id  VARCHAR(100) NOT NULL REFERENCES app_user (id) ON DELETE RESTRICT,
    PRIMARY KEY (section_id, instructor_id)
);

CREATE TABLE section_equipment (                      -- optional portable equipment a section needs (TR2.3)
    section_id    VARCHAR(36) NOT NULL REFERENCES section (id)   ON DELETE CASCADE,
    equipment_id  VARCHAR(36) NOT NULL REFERENCES equipment (id) ON DELETE RESTRICT,
    units         INTEGER     NOT NULL DEFAULT 1,
    PRIMARY KEY (section_id, equipment_id),
    CONSTRAINT ck_section_equipment_units CHECK (units > 0)
);

-- ---------- Bookings: one queue for rooms and equipment (TR2.6, TR4.5) ----------

CREATE TABLE booking (
    id             VARCHAR(36)  PRIMARY KEY,
    requester_id   VARCHAR(100) NOT NULL REFERENCES app_user (id) ON DELETE RESTRICT,
    resource_type  VARCHAR(10)  NOT NULL,
    room_id        VARCHAR(36)  REFERENCES room (id)      ON DELETE RESTRICT,
    equipment_id   VARCHAR(36)  REFERENCES equipment (id) ON DELETE RESTRICT,
    start_time     TIMESTAMP    NOT NULL,
    end_time       TIMESTAMP    NOT NULL,
    purpose        VARCHAR(500) NOT NULL,
    status         VARCHAR(10)  NOT NULL DEFAULT 'PENDING',
    created_at     TIMESTAMP    NOT NULL,
    decided_by     VARCHAR(100) REFERENCES app_user (id) ON DELETE RESTRICT,
    decided_at     TIMESTAMP,
    cancel_note    VARCHAR(500),
    CONSTRAINT ck_booking_type CHECK (resource_type IN ('ROOM', 'EQUIPMENT')),
    CONSTRAINT ck_booking_status CHECK (status IN ('PENDING', 'APPROVED', 'CANCELLED')),
    CONSTRAINT ck_booking_window CHECK (start_time < end_time),
    -- exactly one resource, and it must match the declared type (TR2.6)
    CONSTRAINT ck_booking_one_resource CHECK (
        (resource_type = 'ROOM'      AND room_id IS NOT NULL AND equipment_id IS NULL) OR
        (resource_type = 'EQUIPMENT' AND equipment_id IS NOT NULL AND room_id IS NULL))
);

-- The approval overlap query is: resource = ? AND status = 'APPROVED' AND start_time < :end AND :start < end_time
-- (touching windows do not overlap). NFR3.1 is NOT enforced here: the service locks the room/equipment row
-- first (SELECT ... FOR UPDATE), then runs this query inside the same transaction.
CREATE INDEX ix_booking_room      ON booking (room_id, status, start_time, end_time);
CREATE INDEX ix_booking_equipment ON booking (equipment_id, status, start_time, end_time);
CREATE INDEX ix_booking_queue     ON booking (status, created_at);
CREATE INDEX ix_booking_requester ON booking (requester_id);

-- ---------- Instructor availability (TR2.7) ----------
-- Read-only once the term is PUBLISHED (NFR3.4): enforced by the service from term.status, so no flag here.

CREATE TABLE instructor_availability (
    id             VARCHAR(36)  PRIMARY KEY,
    term_id        VARCHAR(36)  NOT NULL REFERENCES term (id)     ON DELETE CASCADE,
    instructor_id  VARCHAR(100) NOT NULL REFERENCES app_user (id) ON DELETE CASCADE,
    day_of_week    VARCHAR(10)  NOT NULL,
    start_time     TIME         NOT NULL,
    end_time       TIME         NOT NULL,
    status         VARCHAR(12)  NOT NULL,
    CONSTRAINT ck_avail_status CHECK (status IN ('OPEN', 'PREFER', 'UNAVAILABLE')),
    CONSTRAINT ck_avail_day CHECK (day_of_week IN
        ('MONDAY', 'TUESDAY', 'WEDNESDAY', 'THURSDAY', 'FRIDAY', 'SATURDAY', 'SUNDAY')),
    CONSTRAINT ck_avail_window CHECK (start_time < end_time),
    CONSTRAINT uq_avail_block UNIQUE (term_id, instructor_id, day_of_week, start_time)
);
CREATE INDEX ix_avail_instructor ON instructor_availability (term_id, instructor_id);

-- UC-14 also saves a free-text note and the portable equipment the instructor's courses need.
CREATE TABLE availability_submission (
    term_id        VARCHAR(36)  NOT NULL REFERENCES term (id)     ON DELETE CASCADE,
    instructor_id  VARCHAR(100) NOT NULL REFERENCES app_user (id) ON DELETE CASCADE,
    notes          VARCHAR(2000),
    submitted_at   TIMESTAMP    NOT NULL,
    PRIMARY KEY (term_id, instructor_id)
);

CREATE TABLE instructor_equipment_need (
    term_id        VARCHAR(36)  NOT NULL REFERENCES term (id)     ON DELETE CASCADE,
    instructor_id  VARCHAR(100) NOT NULL REFERENCES app_user (id) ON DELETE CASCADE,
    item_type      VARCHAR(100) NOT NULL,                  -- "projector", "laptop cart", "mic kit"
    PRIMARY KEY (term_id, instructor_id, item_type)
);

-- ---------- Conflicts and their audit trail (TR2.8, NFR3.3) ----------

CREATE TABLE conflict (
    id               VARCHAR(36)   PRIMARY KEY,
    term_id          VARCHAR(36)   NOT NULL REFERENCES term (id) ON DELETE CASCADE,
    conflict_type    VARCHAR(30)   NOT NULL,
    severity         VARCHAR(10)   NOT NULL,
    explanation      VARCHAR(1000) NOT NULL,               -- plain language, names the sections (NFR4.1)
    resolution_state VARCHAR(10)   NOT NULL DEFAULT 'OPEN',
    -- Stable identity of the problem, e.g. 'ROOM_DOUBLE_BOOKING:S1:S2'. A re-scan finds the existing row instead of
    -- inserting a duplicate, and a DISMISSED conflict does not come back as a fresh OPEN one.
    fingerprint      VARCHAR(255)  NOT NULL,
    detected_at      TIMESTAMP     NOT NULL,
    resolved_at      TIMESTAMP,
    -- Real references so Reassign / Open in timetable can act directly (TR2.8). Sections are in conflict_section.
    room_id          VARCHAR(36)   REFERENCES room (id)       ON DELETE RESTRICT,
    instructor_id    VARCHAR(100)  REFERENCES app_user (id)   ON DELETE RESTRICT,
    equipment_id     VARCHAR(36)   REFERENCES equipment (id)  ON DELETE RESTRICT,
    booking_id       VARCHAR(36)   REFERENCES booking (id)    ON DELETE RESTRICT,
    CONSTRAINT ck_conflict_type CHECK (conflict_type IN ('ROOM_DOUBLE_BOOKING', 'INSTRUCTOR_OVERLAP',
        'INSTRUCTOR_UNAVAILABLE', 'EQUIPMENT_DOUBLE_BOOKING', 'CAPACITY_EXCEEDED', 'STUDENT_GROUP_CLASH')),
    CONSTRAINT ck_conflict_severity CHECK (severity IN ('HIGH', 'MEDIUM', 'LOW')),
    CONSTRAINT ck_conflict_state CHECK (resolution_state IN ('OPEN', 'RESOLVED', 'DISMISSED')),
    CONSTRAINT uq_conflict_fingerprint UNIQUE (term_id, fingerprint)
);
CREATE INDEX ix_conflict_queue ON conflict (term_id, resolution_state, severity);

CREATE TABLE conflict_section (
    conflict_id  VARCHAR(36) NOT NULL REFERENCES conflict (id) ON DELETE CASCADE,
    section_id   VARCHAR(36) NOT NULL REFERENCES section (id)  ON DELETE CASCADE,
    PRIMARY KEY (conflict_id, section_id)
);
CREATE INDEX ix_conflict_section_section ON conflict_section (section_id);

-- Who dismissed which conflict, when and why. Deliberately NOT a foreign key to conflict, and it keeps a snapshot of
-- the conflict, so the record outlives a deleted term or timetable (an overridden warning must stay auditable).
CREATE TABLE audit_log_entry (
    id                   VARCHAR(36)   PRIMARY KEY,
    conflict_id          VARCHAR(36)   NOT NULL,
    conflict_type        VARCHAR(30)   NOT NULL,
    conflict_explanation VARCHAR(1000) NOT NULL,
    user_id              VARCHAR(100)  NOT NULL REFERENCES app_user (id) ON DELETE RESTRICT,
    occurred_at          TIMESTAMP     NOT NULL,
    reason               VARCHAR(500)  NOT NULL            -- UC-05 4b: confirmation and a reason are required
);
CREATE INDEX ix_audit_conflict ON audit_log_entry (conflict_id);

-- ---------- Insights (TR2.9): advisory, kept apart from conflicts (NFR4.4) ----------

CREATE TABLE insight_suggestion (
    id                  VARCHAR(36)   PRIMARY KEY,
    term_id             VARCHAR(36)   NOT NULL REFERENCES term (id) ON DELETE CASCADE,
    axis                VARCHAR(25)   NOT NULL,
    measure             VARCHAR(10),                       -- rooms only: OCCUPANCY or FILL (FR5.2)
    instructor_id       VARCHAR(100)  REFERENCES app_user (id) ON DELETE CASCADE,
    room_id             VARCHAR(36)   REFERENCES room (id)     ON DELETE CASCADE,
    related_conflict_id VARCHAR(36)   REFERENCES conflict (id) ON DELETE SET NULL,   -- "Already flagged" (FR5.4)
    message             VARCHAR(1000) NOT NULL,
    dismissed           BOOLEAN       NOT NULL DEFAULT FALSE,                        -- dismissible without being resolved (FR5.3)
    created_at          TIMESTAMP     NOT NULL,
    CONSTRAINT ck_insight_axis CHECK (axis IN ('INSTRUCTOR_UTILIZATION', 'ROOM_CAPACITY')),
    CONSTRAINT ck_insight_measure CHECK (measure IS NULL OR measure IN ('OCCUPANCY', 'FILL')),
    -- it concerns exactly the entity its axis names (TR2.9)
    CONSTRAINT ck_insight_subject CHECK (
        (axis = 'INSTRUCTOR_UTILIZATION' AND instructor_id IS NOT NULL AND room_id IS NULL AND measure IS NULL) OR
        (axis = 'ROOM_CAPACITY'          AND room_id IS NOT NULL AND instructor_id IS NULL))
);
CREATE INDEX ix_insight_term ON insight_suggestion (term_id, dismissed);

-- ---------- Import (TR2.10) ----------

CREATE TABLE import_batch (
    id           VARCHAR(36)  PRIMARY KEY,
    file_name    VARCHAR(255) NOT NULL,
    import_type  VARCHAR(25)  NOT NULL,
    imported_at  TIMESTAMP    NOT NULL,
    imported_by  VARCHAR(100) NOT NULL REFERENCES app_user (id) ON DELETE RESTRICT,
    CONSTRAINT ck_import_type CHECK (import_type IN ('READY_MADE_SCHEDULE', 'SUBJECT_LIST', 'ROOMS', 'EQUIPMENT'))
);

CREATE TABLE import_row (
    batch_id  VARCHAR(36)  NOT NULL REFERENCES import_batch (id) ON DELETE CASCADE,
    row_no    INTEGER      NOT NULL,                       -- 1-based data row (header excluded)
    outcome   VARCHAR(12)  NOT NULL,
    reason    VARCHAR(500),
    PRIMARY KEY (batch_id, row_no),
    CONSTRAINT ck_import_outcome CHECK (outcome IN ('ADDED', 'NEEDS_REVIEW')),
    CONSTRAINT ck_import_row_no CHECK (row_no >= 1),
    CONSTRAINT ck_import_reason CHECK (outcome <> 'NEEDS_REVIEW' OR reason IS NOT NULL)   -- FR3.6: always say why
);

-- ---------- Notices (TR2.11) ----------

CREATE TABLE notice (
    id             VARCHAR(36)   PRIMARY KEY,
    recipient_id   VARCHAR(100)  NOT NULL,                 -- Core Platform user id; students are not in app_user, so no FK
    term_id        VARCHAR(36)   REFERENCES term (id)    ON DELETE SET NULL,
    section_id     VARCHAR(36)   REFERENCES section (id) ON DELETE SET NULL,   -- links the dot on the calendar to the change
    trigger_event  VARCHAR(50)   NOT NULL,                 -- ROOM_CHANGED, SECTION_CANCELLED, EXAM_DETAIL, BOOKING_APPROVED ...
    message        VARCHAR(1000) NOT NULL,
    created_at     TIMESTAMP     NOT NULL,
    is_read        BOOLEAN       NOT NULL DEFAULT FALSE
);
CREATE INDEX ix_notice_recipient ON notice (recipient_id, is_read, created_at);

-- ---------- Remaining lookup indexes for the foreign keys used in hot queries ----------
CREATE INDEX ix_section_term       ON section (term_id);
CREATE INDEX ix_section_room       ON section (room_id);
CREATE INDEX ix_section_subject    ON section (subject_id);
CREATE INDEX ix_meeting_section    ON section_meeting (section_id);
CREATE INDEX ix_section_instructor ON section_instructor (instructor_id);
